17	export default function TeamPage() {
18	  const [members, setMembers] = useState<TeamMember[]>([])
19	  const [invites, setInvites] = useState<TeamInvite[]>([])
20	  const [currentUserId, setCurrentUserId] = useState('')
21	  const [loading, setLoading] = useState(true)
22	  const [fetchError, setFetchError] = useState<Error | null>(null)
23	  const [showInviteModal, setShowInviteModal] = useState(false)
24	
25	  const fetchData = useCallback(async () => {
26	    setLoading(true)
27	    setFetchError(null)
28	    try {
29	      const [membersRes, invitesRes, meRes] = await Promise.all([
30	        fetch('/api/studio-members'),
31	        fetch('/api/team-invites'),
32	        fetch('/api/profile'),
33	      ])
34	
35	      if (!membersRes.ok) throw new Error('Failed to fetch members')
36	      const membersJson = await membersRes.json() as { data: TeamMember[] }
37	      setMembers(membersJson.data ?? [])
38	
39	      if (invitesRes.ok) {
40	        const invitesJson = await invitesRes.json() as { data: TeamInvite[] }
41	        setInvites(invitesJson.data ?? [])
42	      }
43	
44	      if (meRes.ok) {
45	        const meJson = await meRes.json() as { data: { id: string } }
46	        setCurrentUserId(meJson.data?.id ?? '')
47	      }
48	    } catch (err) {
49	      setFetchError(err instanceof Error ? err : new Error('Could not load team data'))
50	    } finally {
51	      setLoading(false)
52	    }
53	  }, [])
54	
55	  useEffect(() => { void fetchData() }, [fetchData])
56	
57	  const pendingCount = invites.filter((i) => i.status === 'pending').length
58	  const activeCount = members.filter((m) => !m.deactivated_at).length
59	
60	  return (
61	    <div className="flex flex-col min-h-0">
62	      <div className="flex items-center justify-between px-6 py-4 border-b border-border/50">
63	        <Typography variant="h1">Team &amp; Roles</Typography>
64	        <Button size="sm" onClick={() => setShowInviteModal(true)}>
65	          + Invite Member
66	        </Button>
67	      </div>
68	
69	      <Tabs defaultValue="members" className="mt-0 flex-1">
70	        <TabsList className="w-full justify-start border-b rounded-none bg-transparent h-auto px-6 gap-0">
71	          <TabsTrigger
72	            value="members"
73	            className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium"
74	          >
75	            Members {!loading && `(${activeCount})`}
76	          </TabsTrigger>
77	          <TabsTrigger
78	            value="invites"
79	            className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium"
80	          >
81	            Pending Invites {!loading && pendingCount > 0 && `(${pendingCount})`}
82	          </TabsTrigger>
83	        </TabsList>
84	
85	        <TabsContent value="members" className="mt-0 p-6">
86	          <DataState
87	            data={members}
88	            isLoading={loading}
89	            isError={!!fetchError}
90	            error={fetchError}
91	            loadingSlot={<ListSkeleton rows={4} />}
92	            emptySlot={
93	              <EmptyState
94	                icon={Mail}
95	                title="No team members yet"
96	                description="Invite artists and receptionists to join your studio."
97	                cta={{ label: 'Invite member', onClick: () => setShowInviteModal(true) }}
98	                variant="first-time"
99	              />
100	            }
101	            errorSlot={
102	              <PageError
103	                error={fetchError ?? new Error('Failed to load team')}
104	                reset={() => void fetchData()}
105	                variant="inline"
106	              />
107	            }
108	          >
109	            {(data) => (
110	              <TeamMembersTable
111	                members={data}
112	                currentUserId={currentUserId}
113	                onRefresh={() => void fetchData()}
114	              />
115	            )}
116	          </DataState>
117	        </TabsContent>
118	
119	        <TabsContent value="invites" className="mt-0 p-6">
120	          <DataState
121	            data={invites}
122	            isLoading={loading}
123	            isError={!!fetchError}
124	            error={fetchError}
125	            loadingSlot={<ListSkeleton rows={2} />}
126	            emptySlot={
127	              <EmptyState
128	                icon={Mail}
129	                title="No pending invites"
130	                description="Invited members will appear here until they accept."
131	                variant="default"
132	              />
133	            }
134	          >
135	            {(data) => (
136	              <TeamInvitesTable
137	                invites={data}
138	                onRefresh={() => void fetchData()}
139	              />
140	            )}
141	          </DataState>
142	        </TabsContent>
143	      </Tabs>
144	
145	      {showInviteModal && (
146	        <InviteModal
147	          open={showInviteModal}
148	          onOpenChange={setShowInviteModal}
149	          onSuccess={() => void fetchData()}
150	        />
151	      )}
152	    </div>
153	  )
154	}
