1	'use client'
2	
3	import { useState, useEffect, useCallback } from 'react'
4	import { Button } from '@/components/ui/button'
5	import { Typography } from '@/components/ui/typography'
6	import { Skeleton } from '@/components/ui/skeleton'
7	import { Separator } from '@/components/ui/separator'
8	import { Alert, AlertDescription } from '@/components/ui/alert'
9	import { toast } from 'sonner'
10	import { RefreshCw, Copy, AlertCircle } from 'lucide-react'
11	import { WeekGrid } from './WeekGrid'
12	import { EffectiveDateRange } from './EffectiveDateRange'
13	import { TimeOffPanel } from './TimeOffPanel'
14	import { BlockedDatesPanel } from './BlockedDatesPanel'
15	import { CopyScheduleDialog } from './CopyScheduleDialog'
16	import type { ScheduleSlot, TimeOff, BlockedDate, DayOfWeek } from './types'
17	
18	interface ScheduleEditorProps {
19	  artistId: string
20	  artistName: string
21	  /** Whether the current user can edit this artist's schedule */
22	  canEdit: boolean
23	  /** Whether the current user can approve/deny time-off requests */
24	  canApprove: boolean
25	}
26	
27	export function ScheduleEditor({ artistId, artistName, canEdit, canApprove }: ScheduleEditorProps) {
28	  const [slots, setSlots] = useState<ScheduleSlot[]>([])
29	  const [timeOff, setTimeOff] = useState<TimeOff[]>([])
30	  const [blockedDates, setBlockedDates] = useState<BlockedDate[]>([])
31	
32	  const [loadingSlots, setLoadingSlots] = useState(true)
33	  const [loadingTimeOff, setLoadingTimeOff] = useState(true)
34	  const [loadingBlocked, setLoadingBlocked] = useState(true)
35	  const [slotsError, setSlotsError] = useState<string | null>(null)
36	
37	  const [effectiveFrom, setEffectiveFrom] = useState<string>(
38	    () => new Date().toISOString().slice(0, 10),
39	  )
40	  const [effectiveUntil, setEffectiveUntil] = useState<string>('')
41	
42	  const [copyOpen, setCopyOpen] = useState(false)
43	  const [savingSlot, setSavingSlot] = useState(false)
44	
45	  const fetchSlots = useCallback(async () => {
46	    setLoadingSlots(true)
47	    setSlotsError(null)
48	    try {
49	      const res = await fetch(`/api/artists/${artistId}/schedule`)
50	      if (!res.ok) throw new Error('Failed to fetch schedule')
51	      const json = await res.json() as { data: ScheduleSlot[] }
52	      setSlots(json.data ?? [])
53	    } catch {
54	      setSlotsError('Could not load schedule. Please try again.')
55	    } finally {
56	      setLoadingSlots(false)
57	    }
58	  }, [artistId])
59	
60	  const fetchTimeOff = useCallback(async () => {
61	    setLoadingTimeOff(true)
62	    try {
63	      const res = await fetch(`/api/artists/${artistId}/time-off`)
64	      if (!res.ok) throw new Error('Failed')
65	      const json = await res.json() as { data: TimeOff[] }
66	      setTimeOff(json.data ?? [])
67	    } catch {
68	      setTimeOff([])
69	    } finally {
70	      setLoadingTimeOff(false)
71	    }
72	  }, [artistId])
73	
74	  const fetchBlocked = useCallback(async () => {
75	    setLoadingBlocked(true)
76	    try {
77	      const res = await fetch(`/api/artists/${artistId}/blocked-dates`)
78	      if (!res.ok) throw new Error('Failed')
79	      const json = await res.json() as { data: BlockedDate[] }
80	      setBlockedDates(json.data ?? [])
81	    } catch {
82	      setBlockedDates([])
83	    } finally {
84	      setLoadingBlocked(false)
85	    }
86	  }, [artistId])
87	
88	  useEffect(() => {
89	    void fetchSlots()
90	    void fetchTimeOff()
91	    void fetchBlocked()
92	  }, [fetchSlots, fetchTimeOff, fetchBlocked])
93	
94	  const handleAddSlot = async (dayOfWeek: DayOfWeek, startTime: string, endTime: string) => {
95	    if (!canEdit) return
96	    setSavingSlot(true)
97	    try {
98	      const res = await fetch(`/api/artists/${artistId}/schedule`, {
99	        method: 'POST',
100	        headers: { 'Content-Type': 'application/json' },
101	        body: JSON.stringify({
102	          day_of_week: dayOfWeek,
103	          start_time: startTime,
104	          end_time: endTime,
105	          effective_from: effectiveFrom || undefined,
106	          effective_until: effectiveUntil || null,
107	        }),
108	      })
109	      const json = await res.json() as { data?: ScheduleSlot; error?: string }
110	      if (!res.ok) throw new Error(json.error ?? 'Failed to add slot')
111	      if (json.data) setSlots((prev) => [...prev, json.data!])
112	      toast.success('Slot added')
113	    } catch (err) {
114	      const message = err instanceof Error ? err.message : 'Failed to add slot'
115	      toast.error(message)
116	    } finally {
117	      setSavingSlot(false)
118	    }
119	  }
120	
121	  const handleDeleteSlot = async (id: string) => {
122	    if (!canEdit) return
123	    // Optimistic remove
124	    setSlots((prev) => prev.filter((s) => s.id !== id))
125	    try {
126	      const res = await fetch(`/api/artists/${artistId}/schedule`, {
127	        method: 'DELETE',
128	        headers: { 'Content-Type': 'application/json' },
129	        body: JSON.stringify({ ids: [id] }),
130	      })
131	      if (!res.ok) throw new Error('Failed to delete slot')
132	      toast.success('Slot removed')
133	    } catch {
134	      toast.error('Failed to remove slot')
135	      void fetchSlots() // rollback
136	    }
137	  }
138	
139	  return (
140	    <div className="space-y-6">
141	      {/* Header */}
142	      <div className="flex items-center justify-between gap-3 flex-wrap">
143	        <div>
144	          <Typography variant="h2">Weekly Schedule</Typography>
145	          <p className="text-xs text-muted-foreground mt-0.5">
146	            Set recurring availability by day of week.
147	          </p>
148	        </div>
149	        <div className="flex items-center gap-2">
150	          <Button
151	            type="button"
152	            variant="ghost"
153	            size="sm"
154	            className="h-7 gap-1.5 text-xs"
155	            onClick={() => { void fetchSlots() }}
156	            disabled={loadingSlots}
157	          >
158	            <RefreshCw className={`h-3.5 w-3.5 ${loadingSlots ? 'animate-spin' : ''}`} />
159	            Refresh
160	          </Button>
161	          {canEdit && (
162	            <Button
163	              type="button"
164	              variant="outline"
165	              size="sm"
166	              className="h-7 gap-1.5 text-xs"
167	              onClick={() => setCopyOpen(true)}
168	            >
169	              <Copy className="h-3.5 w-3.5" />
170	              Copy from…
171	            </Button>
172	          )}
173	        </div>
174	      </div>
175	
176	      {/* Effective date range (applies to newly added slots) */}
177	      {canEdit && (
178	        <EffectiveDateRange
179	          effectiveFrom={effectiveFrom}
180	          effectiveUntil={effectiveUntil}
181	          onEffectiveFromChange={setEffectiveFrom}
182	          onEffectiveUntilChange={setEffectiveUntil}
183	        />
184	      )}
185	
186	      {/* Error state */}
187	      {slotsError && !loadingSlots && (
188	        <Alert variant="destructive">
189	          <AlertCircle className="h-4 w-4" />
190	          <AlertDescription className="flex items-center justify-between">
191	            <span>{slotsError}</span>
192	            <Button variant="ghost" size="sm" className="h-7" onClick={() => void fetchSlots()}>
193	              <RefreshCw className="h-3.5 w-3.5 mr-1.5" />
194	              Retry
195	            </Button>
196	          </AlertDescription>
197	        </Alert>
198	      )}
199	
200	      {/* Week grid skeleton */}
201	      {loadingSlots ? (
202	        <div className="grid grid-cols-7 gap-2">
203	          {Array.from({ length: 7 }).map((_, i) => (
204	            <Skeleton key={i} className="h-28 rounded-lg" />
205	          ))}
206	        </div>
207	      ) : (
208	        <WeekGrid
209	          slots={slots}
210	          onAddSlot={handleAddSlot}
211	          onDeleteSlot={handleDeleteSlot}
212	          disabled={!canEdit || savingSlot}
213	        />
214	      )}
215	
216	      <Separator />
217	
218	      {/* Time off + blocked dates */}
219	      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
220	        <TimeOffPanel
221	          artistId={artistId}
222	          timeOff={timeOff}
223	          loading={loadingTimeOff}
224	          canApprove={canApprove}
225	          onRefresh={() => void fetchTimeOff()}
226	        />
227	        <BlockedDatesPanel
228	          artistId={artistId}
229	          blockedDates={blockedDates}
230	          loading={loadingBlocked}
231	          canEdit={canEdit}
232	          onRefresh={() => void fetchBlocked()}
233	        />
234	      </div>
235	
236	      <CopyScheduleDialog
237	        open={copyOpen}
238	        onOpenChange={setCopyOpen}
239	        sourceArtistId={artistId}
240	        sourceArtistName={artistName}
241	        onSuccess={() => void fetchSlots()}
242	      />
243	    </div>
244	  )
245	}
